enum Step<T> { Done(T), More(Box<dyn FnOnce() -> Step<T>>) }

fn even(n: u64) -> Step<bool> { if n == 0 { Step::Done(true) } else { Step::More(Box::new(move || odd(n - 1))) } }
fn odd(n: u64) -> Step<bool>  { if n == 0 { Step::Done(false) } else { Step::More(Box::new(move || even(n - 1))) } }

