enum Step<T, S> { Done(T), Bounce(fn(S) -> Step<T, S>, S) }

fn even(n: u64) -> Step<bool, u64> { if n == 0 { Step::Done(true) } else { Step::Bounce(odd_at, n - 1) } }
fn odd_at(n: u64) -> Step<bool, u64> { if n == 0 { Step::Done(false) } else { Step::Bounce(even, n - 1) } }

fn run<T, S>(mut s: Step<T, S>) -> T {
    loop { match s { Step::Done(v) => return v, Step::Bounce(f, st) => s = f(st) } }
}
